using System;
using System.Collections.Generic;
using UnityEngine;
using Framework.Grid;

namespace Framework.Generation
{
    #region Maze Cell Type

    /// <summary>
    /// 迷路生成に使用する基本的なマスの種類。
    /// ゲーム固有のマスデータとは独立して管理する。
    /// </summary>
    public enum MazeCellType
    {
        /// <summary>移動可能な通路。</summary>
        Passage = 0,

        /// <summary>移動不可能な壁。</summary>
        Wall = 1
    }

    #endregion

    #region Generation Settings

    /// <summary>
    /// 迷路の生成条件を管理する設定クラス。
    /// UnityのInspectorから設定することも可能。
    /// </summary>
    [Serializable]
    public sealed class MazeGenerationSettings
    {
        [Header("マップサイズ")]

        /// <summary>迷路の横方向のマス数。</summary>
        [Min(5)]
        [Tooltip("迷路の横幅。偶数の場合は1を加えて奇数に補正します。")]
        public int Width = 15;

        /// <summary>迷路の縦方向のマス数。</summary>
        [Min(5)]
        [Tooltip("迷路の縦幅。偶数の場合は1を加えて奇数に補正します。")]
        public int Height = 11;

        [Header("乱数設定")]

        /// <summary>固定シード値を使用するかどうか。</summary>
        [Tooltip("有効にすると同じ設定から同じ迷路を生成します。")]
        public bool UseFixedSeed = false;

        /// <summary>迷路生成に使用する固定シード値。</summary>
        [Tooltip("固定シードを使用する場合の乱数シード値")]
        public int Seed = 12345;

        [Header("通路生成設定")]

        /// <summary>
        /// 追加通路の生成割合。
        /// 0の場合は追加通路を生成しない。
        /// </summary>
        [Range(0f, 1f)]
        [Tooltip("周回経路を増やすために追加で取り除く壁の割合")]
        public float LoopRate = 0.2f;

        /// <summary>
        /// 行き止まりを解消する際の処理割合。
        /// </summary>
        [Range(0f, 1f)]
        [Tooltip("行き止まりを別の通路へ接続する割合")]
        public float DeadEndRemovalRate = 0.8f;
    }

    #endregion

    #region Generation Result

    /// <summary>
    /// 迷路の生成結果と統計情報を保持するクラス。
    /// 統計情報は生成完了時点の値を保持する。
    /// </summary>
    public sealed class MazeGenerationResult
    {
        /// <summary>生成された迷路のマップデータ。</summary>
        public GridMap<MazeCellType> Map { get; }

        /// <summary>実際に使用された乱数シード値。</summary>
        public int Seed { get; }

        /// <summary>生成された迷路の横幅。</summary>
        public int Width => Map.Width;

        /// <summary>生成された迷路の縦幅。</summary>
        public int Height => Map.Height;

        /// <summary>生成完了時点の通路の数。</summary>
        public int PassageCount { get; }

        /// <summary>生成完了時点の壁の数。</summary>
        public int WallCount { get; }

        /// <summary>生成完了時点の行き止まりの数。</summary>
        public int DeadEndCount { get; }

        /// <summary>追加で開通させた壁の数。</summary>
        public int AddedPassageCount { get; }

        /// <summary>マップ全体に占める通路の割合。</summary>
        public float PassageRate =>
            (float)PassageCount / Map.Count;

        /// <summary>
        /// 迷路の生成結果を作成する。
        /// </summary>
        /// <param name="map">生成された迷路</param>
        /// <param name="seed">使用したシード値</param>
        /// <param name="passageCount">通路数</param>
        /// <param name="wallCount">壁数</param>
        /// <param name="deadEndCount">行き止まり数</param>
        /// <param name="addedPassageCount">追加通路数</param>
        internal MazeGenerationResult(
            GridMap<MazeCellType> map,
            int seed,
            int passageCount,
            int wallCount,
            int deadEndCount,
            int addedPassageCount)
        {
            Map = map;
            Seed = seed;
            PassageCount = passageCount;
            WallCount = wallCount;
            DeadEndCount = deadEndCount;
            AddedPassageCount = addedPassageCount;
        }

        /// <summary>
        /// 迷路を任意のマスデータ型に変換する。
        /// 元の迷路データは変更しない。
        /// </summary>
        /// <typeparam name="T">変換先のマスデータ型</typeparam>
        /// <param name="converter">マスデータの変換処理</param>
        /// <returns>変換後のグリッドマップ</returns>
        public GridMap<T> ConvertTo<T>(
            Func<Vector2Int, MazeCellType, T> converter)
        {
            if (converter == null)
            {
                throw new ArgumentNullException(
                    nameof(converter));
            }

            return new GridMap<T>(
                Width,
                Height,
                position =>
                    converter(position, Map.GetCell(position)));
        }
    }

    #endregion

    #region Maze Generator

    /// <summary>
    /// 穴掘り法を利用して迷路を自動生成する汎用クラス。
    ///
    /// 深さ優先探索による基本迷路の生成、
    /// 周回経路の追加、行き止まりの削減に対応する。
    ///
    /// MonoBehaviourには依存しない。
    /// </summary>
    public static class MazeGenerator
    {
        #region Fields

        /// <summary>
        /// 上下左右の4方向を表す移動ベクトル。
        /// </summary>
        private static readonly Vector2Int[] Directions =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        #endregion

        #region Public Methods

        /// <summary>
        /// 指定された設定に従って迷路を生成する。
        /// </summary>
        /// <param name="settings">迷路生成設定</param>
        /// <returns>迷路の生成結果</returns>
        public static MazeGenerationResult Generate(
            MazeGenerationSettings settings)
        {
            if (settings == null)
            {
                throw new ArgumentNullException(
                    nameof(settings));
            }

            // 穴掘り法に適した奇数サイズへ補正する。
            int width = NormalizeSize(settings.Width);
            int height = NormalizeSize(settings.Height);

            // 使用するシード値を決定する。
            int seed = settings.UseFixedSeed
                ? settings.Seed
                : Guid.NewGuid().GetHashCode();

            // Unity全体の乱数状態に影響を与えないよう、
            // 専用の乱数生成器を使用する。
            System.Random random =
                new System.Random(seed);

            // 全マスを壁で初期化する。
            GridMap<MazeCellType> map =
                new GridMap<MazeCellType>(
                    width,
                    height,
                    position => MazeCellType.Wall);

            // STEP 1：基本となる迷路を生成する。
            GenerateBaseMaze(map, random);

            // STEP 2：行き止まりを削減する。
            int removedDeadEnds = RemoveDeadEnds(
                map,
                random,
                Mathf.Clamp01(settings.DeadEndRemovalRate));

            // STEP 3：周回可能な通路を追加する。
            int addedLoops = AddLoops(
                map,
                random,
                Mathf.Clamp01(settings.LoopRate));

            // 生成完了後の統計情報を取得する。
            int passageCount = map.CountCells(
                cell => cell == MazeCellType.Passage);

            int wallCount = map.Count - passageCount;

            int deadEndCount = CountDeadEnds(map);

            // 生成結果を返す。
            return new MazeGenerationResult(
                map,
                seed,
                passageCount,
                wallCount,
                deadEndCount,
                removedDeadEnds + addedLoops);
        }

        /// <summary>
        /// 横幅と縦幅を指定して迷路を生成する。
        /// その他の設定には初期値を使用する。
        /// </summary>
        /// <param name="width">迷路の横幅</param>
        /// <param name="height">迷路の縦幅</param>
        /// <returns>迷路の生成結果</returns>
        public static MazeGenerationResult Generate(
            int width,
            int height)
        {
            MazeGenerationSettings settings =
                new MazeGenerationSettings
                {
                    Width = width,
                    Height = height
                };

            return Generate(settings);
        }

        /// <summary>
        /// 指定されたマスが行き止まりかどうか判定する。
        /// </summary>
        /// <param name="map">判定対象の迷路</param>
        /// <param name="position">判定対象の座標</param>
        /// <returns>行き止まりの場合はtrue</returns>
        public static bool IsDeadEnd(
            GridMap<MazeCellType> map,
            Vector2Int position)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            if (!IsPassage(map, position))
            {
                return false;
            }

            // 接続されている通路が1つの場合は行き止まり。
            return CountPassageNeighbors(map, position) == 1;
        }

        /// <summary>
        /// 迷路内に存在する行き止まりの数を取得する。
        /// </summary>
        /// <param name="map">判定対象の迷路</param>
        /// <returns>行き止まりの数</returns>
        public static int CountDeadEnds(
            GridMap<MazeCellType> map)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            int count = 0;

            foreach (Vector2Int position in map.GetPositions())
            {
                if (IsDeadEnd(map, position))
                {
                    count++;
                }
            }

            return count;
        }

        /// <summary>
        /// すべての通路が互いに接続されているか確認する。
        /// 幅優先探索を使用して到達可能なマスを調べる。
        /// </summary>
        /// <param name="map">確認対象の迷路</param>
        /// <returns>すべての通路が接続されている場合はtrue</returns>
        public static bool IsFullyConnected(
            GridMap<MazeCellType> map)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            // 探索開始位置と通路の総数を取得する。
            Vector2Int start = Vector2Int.zero;
            int passageCount = 0;

            foreach (Vector2Int position in map.GetPositions())
            {
                if (!IsPassage(map, position))
                {
                    continue;
                }

                if (passageCount == 0)
                {
                    start = position;
                }

                passageCount++;
            }

            // 通路が存在しない場合は無効な迷路とする。
            if (passageCount == 0)
            {
                return false;
            }

            // 探索済みのマスを管理する。
            HashSet<Vector2Int> visited =
                new HashSet<Vector2Int>();

            // 探索待ちのマスを管理する。
            Queue<Vector2Int> queue =
                new Queue<Vector2Int>();

            visited.Add(start);
            queue.Enqueue(start);

            // 幅優先探索によって通路を順番に調べる。
            while (queue.Count > 0)
            {
                Vector2Int current = queue.Dequeue();

                foreach (Vector2Int direction in Directions)
                {
                    Vector2Int next = current + direction;

                    if (!IsPassage(map, next))
                    {
                        continue;
                    }

                    if (!visited.Add(next))
                    {
                        continue;
                    }

                    queue.Enqueue(next);
                }
            }

            // 到達した通路数と全通路数を比較する。
            return visited.Count == passageCount;
        }

        #endregion

        #region Base Maze Generation

        /// <summary>
        /// 深さ優先探索を利用して基本迷路を生成する。
        /// 2マス先へ移動しながら間の壁を取り除く。
        /// </summary>
        /// <param name="map">生成対象の迷路</param>
        /// <param name="random">乱数生成器</param>
        private static void GenerateBaseMaze(
            GridMap<MazeCellType> map,
            System.Random random)
        {
            // 奇数座標に位置するマスから探索を開始する。
            Vector2Int start = new Vector2Int(
                random.Next(map.Width / 2) * 2 + 1,
                random.Next(map.Height / 2) * 2 + 1);

            // 探索経路を保持するスタック。
            Stack<Vector2Int> stack =
                new Stack<Vector2Int>();

            // 次の移動先候補を格納するリスト。
            List<Vector2Int> candidates =
                new List<Vector2Int>(4);

            map.SetCell(start, MazeCellType.Passage);

            stack.Push(start);

            while (stack.Count > 0)
            {
                // 現在の探索位置を取得する。
                Vector2Int current = stack.Peek();

                candidates.Clear();

                // 2マス先にある未探索のマスを調べる。
                foreach (Vector2Int direction in Directions)
                {
                    Vector2Int next =
                        current + direction * 2;

                    if (!IsInnerCell(map, next))
                    {
                        continue;
                    }

                    if (map.GetCell(next) != MazeCellType.Wall)
                    {
                        continue;
                    }

                    candidates.Add(next);
                }

                // 移動可能な場所がない場合は、
                // 直前の探索位置まで戻る。
                if (candidates.Count == 0)
                {
                    stack.Pop();
                    continue;
                }

                // 候補からランダムに移動先を選択する。
                Vector2Int destination =
                    candidates[random.Next(candidates.Count)];

                // 現在位置と移動先の間にある壁の座標。
                Vector2Int between =
                    current + (destination - current) / 2;

                // 間の壁と移動先を通路へ変更する。
                map.SetCell(between, MazeCellType.Passage);

                map.SetCell(
                    destination,
                    MazeCellType.Passage);

                // 次の探索位置を登録する。
                stack.Push(destination);
            }
        }

        #endregion

        #region Dead End Removal

        /// <summary>
        /// 行き止まりから別の通路へ接続する。
        /// 外周の壁は取り除かない。
        /// </summary>
        /// <param name="map">処理対象の迷路</param>
        /// <param name="random">乱数生成器</param>
        /// <param name="rate">行き止まりの処理割合</param>
        /// <returns>追加で開通させた壁の数</returns>
        private static int RemoveDeadEnds(
            GridMap<MazeCellType> map,
            System.Random random,
            float rate)
        {
            if (rate <= 0f)
            {
                return 0;
            }

            // 現在存在する行き止まりを取得する。
            List<Vector2Int> deadEnds =
                new List<Vector2Int>();

            foreach (Vector2Int position in map.GetPositions())
            {
                if (IsDeadEnd(map, position))
                {
                    deadEnds.Add(position);
                }
            }

            // 特定の方向に処理が偏らないように並べ替える。
            Shuffle(deadEnds, random);

            // 接続可能な壁を格納するリスト。
            List<Vector2Int> candidates =
                new List<Vector2Int>(4);

            int removedCount = 0;

            foreach (Vector2Int position in deadEnds)
            {
                // 他の壁の除去によって既に行き止まりが
                // 解消されている場合は処理しない。
                if (!IsDeadEnd(map, position))
                {
                    continue;
                }

                // 指定された割合に従って処理する。
                if (random.NextDouble() >= rate)
                {
                    continue;
                }

                candidates.Clear();

                foreach (Vector2Int direction in Directions)
                {
                    // 隣接する壁と、その先のマスを取得する。
                    Vector2Int wallPosition =
                        position + direction;

                    Vector2Int destination =
                        position + direction * 2;

                    if (!IsInnerCell(map, wallPosition))
                    {
                        continue;
                    }

                    if (map.GetCell(wallPosition)
                        != MazeCellType.Wall)
                    {
                        continue;
                    }

                    // 壁の先が既存の通路である場合のみ
                    // 接続候補として登録する。
                    if (IsPassage(map, destination))
                    {
                        candidates.Add(wallPosition);
                    }
                }

                if (candidates.Count == 0)
                {
                    continue;
                }

                // 接続候補からランダムに壁を選択する。
                Vector2Int selectedWall =
                    candidates[random.Next(candidates.Count)];

                map.SetCell(
                    selectedWall,
                    MazeCellType.Passage);

                removedCount++;
            }

            return removedCount;
        }

        #endregion

        #region Loop Generation

        /// <summary>
        /// 既存の通路間にある壁を取り除き、
        /// 周回可能な経路を追加する。
        /// </summary>
        /// <param name="map">処理対象の迷路</param>
        /// <param name="random">乱数生成器</param>
        /// <param name="rate">追加通路の生成割合</param>
        /// <returns>追加で開通させた壁の数</returns>
        private static int AddLoops(
            GridMap<MazeCellType> map,
            System.Random random,
            float rate)
        {
            if (rate <= 0f)
            {
                return 0;
            }

            // 取り除くことのできる壁の候補。
            List<Vector2Int> candidates =
                new List<Vector2Int>();

            foreach (Vector2Int position in map.GetPositions())
            {
                if (!IsInnerCell(map, position))
                {
                    continue;
                }

                if (map.GetCell(position) != MazeCellType.Wall)
                {
                    continue;
                }

                // 偶数・偶数座標の壁は柱として維持する。
                // 広い空間ができすぎることを防止する。
                if (position.x % 2 == 0 &&
                    position.y % 2 == 0)
                {
                    continue;
                }

                // 左右の通路が壁を挟んで存在するか確認する。
                bool horizontal =
                    IsPassage(
                        map, position + Vector2Int.left) &&
                    IsPassage(
                        map, position + Vector2Int.right);

                // 上下の通路が壁を挟んで存在するか確認する。
                bool vertical =
                    IsPassage(
                        map, position + Vector2Int.up) &&
                    IsPassage(
                        map, position + Vector2Int.down);

                if (horizontal || vertical)
                {
                    candidates.Add(position);
                }
            }

            // ランダムな順番で壁を取り除く。
            Shuffle(candidates, random);

            // 候補数と生成割合から開通数を決定する。
            int targetCount = Mathf.Clamp(
                Mathf.RoundToInt(candidates.Count * rate),
                0,
                candidates.Count);

            for (int i = 0; i < targetCount; i++)
            {
                map.SetCell(
                    candidates[i],
                    MazeCellType.Passage);
            }

            return targetCount;
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// マップサイズを迷路生成に適した奇数へ補正する。
        /// 最小サイズは5とする。
        /// </summary>
        /// <param name="size">補正前のサイズ</param>
        /// <returns>補正後のサイズ</returns>
        private static int NormalizeSize(int size)
        {
            size = Mathf.Max(5, size);

            if (size % 2 == 0)
            {
                size++;
            }

            return size;
        }

        /// <summary>
        /// 指定座標が外周を除いたマップ内部か確認する。
        /// </summary>
        /// <param name="map">判定対象の迷路</param>
        /// <param name="position">判定対象の座標</param>
        /// <returns>マップ内部の場合はtrue</returns>
        private static bool IsInnerCell(
            GridMap<MazeCellType> map,
            Vector2Int position)
        {
            return position.x > 0 &&
                   position.y > 0 &&
                   position.x < map.Width - 1 &&
                   position.y < map.Height - 1;
        }

        /// <summary>
        /// 指定座標が通路かどうか判定する。
        /// マップ範囲外の場合はfalseを返す。
        /// </summary>
        /// <param name="map">判定対象の迷路</param>
        /// <param name="position">判定対象の座標</param>
        /// <returns>通路の場合はtrue</returns>
        private static bool IsPassage(
            GridMap<MazeCellType> map,
            Vector2Int position)
        {
            return map.TryGetCell(
                       position,
                       out MazeCellType cell) &&
                   cell == MazeCellType.Passage;
        }

        /// <summary>
        /// 指定座標の上下左右に存在する通路数を取得する。
        /// </summary>
        /// <param name="map">判定対象の迷路</param>
        /// <param name="position">基準となる座標</param>
        /// <returns>隣接する通路の数</returns>
        private static int CountPassageNeighbors(
            GridMap<MazeCellType> map,
            Vector2Int position)
        {
            int count = 0;

            foreach (Vector2Int direction in Directions)
            {
                if (IsPassage(map, position + direction))
                {
                    count++;
                }
            }

            return count;
        }

        /// <summary>
        /// Fisher-Yatesアルゴリズムを使用して
        /// リストの要素をランダムに並べ替える。
        /// </summary>
        /// <typeparam name="T">リストの要素型</typeparam>
        /// <param name="list">並べ替え対象のリスト</param>
        /// <param name="random">乱数生成器</param>
        private static void Shuffle<T>(
            List<T> list,
            System.Random random)
        {
            for (int i = list.Count - 1; i > 0; i--)
            {
                int j = random.Next(i + 1);

                T temporary = list[i];

                list[i] = list[j];

                list[j] = temporary;
            }
        }

        #endregion
    }

    #endregion
}
